#define N_TR (int)(sizeof(table) / sizeof(table[0]))
#define HSIZE 4096
static short hidx[HSIZE];
static int ready = 0;

static unsigned hash(const char *s)
{
    unsigned h = 2166136261u;
    while (*s) { h ^= (unsigned char)*s++; h *= 16777619u; }
    return h;
}

void lang_init(void)
{
    for (int i = 0; i < HSIZE; i++) hidx[i] = -1;
    for (int i = 0; i < N_TR; i++) {
        unsigned h = hash(table[i].fr) & (HSIZE - 1);
        while (hidx[h] >= 0) h = (h + 1) & (HSIZE - 1);
        hidx[h] = (short)i;
    }
    ready = 1;
}

const char *T(const char *s)
{
    if (!s || g_lang == LANG_FR) return s;
    if (!ready) lang_init();
    unsigned h = hash(s) & (HSIZE - 1);
    while (hidx[h] >= 0) {
        const Tr *t = &table[hidx[h]];
        if (strcmp(t->fr, s) == 0) return g_lang == LANG_EN ? t->en : t->ru;
        h = (h + 1) & (HSIZE - 1);
    }
    return s;
}